package com.climbme.app.dashboard;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.climbme.app.ClimbMeApplication;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.mock.web.MockHttpSession;import org.springframework.test.web.servlet.*;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(classes=ClimbMeApplication.class,properties={"spring.datasource.url=jdbc:h2:mem:climbme_dashboard;MODE=PostgreSQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=validate"})@AutoConfigureMockMvc @Transactional class DashboardIntegrationTest{@Autowired MockMvc mvc;@Test void dashboardIsPrivateAndCalculatesSends()throws Exception{MockHttpSession a=register("dash@example.com"),b=register("otherdash@example.com");create(a,"7a","REDPOINT",true);create(a,"6c","PROJECT",false);mvc.perform(get("/api/dashboard").session(a)).andExpect(status().isOk()).andExpect(jsonPath("$.kpis.totalAttempts").value(2)).andExpect(jsonPath("$.kpis.totalSends").value(1)).andExpect(jsonPath("$.kpis.hardestRedpoint").value("7a"));mvc.perform(get("/api/dashboard").session(b)).andExpect(jsonPath("$.kpis.totalAttempts").value(0));}MockHttpSession register(String email)throws Exception{MvcResult r=mvc.perform(post("/api/auth/register").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"safe-password-123\"}")).andReturn();return(MockHttpSession)r.getRequest().getSession(false);}void create(MockHttpSession s,String grade,String style,boolean sent)throws Exception{mvc.perform(post("/api/attempts").session(s).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"climbedOn\":\"2026-08-12\",\"location\":\"Osp\",\"sector\":\"Misja Pec\",\"routeName\":\"R"+grade+"\",\"grade\":\""+grade+"\",\"style\":\""+style+"\",\"sent\":"+sent+"}")).andExpect(status().isCreated());}}
